insert into public.nongkum_schedule_schools(school_id,name,short_name,aliases)
select x.school_id,x.name,x.short_name,x.aliases from jsonb_to_recordset('[{"school_id":"nongkum","name":"โรงเรียนบ้านหนองกุ่ม","short_name":"หนองกุ่ม","aliases":["nongkum","โรงเรียนบ้านหนองกุ่ม","หนองกุ่ม","บ้านหนองกุ่ม"]},{"school_id":"thungmasang","name":"โรงเรียนวัดทุ่งมะสัง (มิตรภาพที่ 9)","short_name":"ทุ่งมะสังฯ","aliases":["thungmasang","โรงเรียนวัดทุ่งมะสัง (มิตรภาพที่ 9)","ทุ่งมะสังฯ","ทุ่งมะสัง","วัดทุ่งมะสัง"]},{"school_id":"rangkham","name":"โรงเรียนบ้านรางขาม","short_name":"รางขาม","aliases":["rangkham","โรงเรียนบ้านรางขาม","รางขาม","บ้านรางขาม"]},{"school_id":"wangdong","name":"โรงเรียนบ้านวังด้ง","short_name":"วังด้ง","aliases":["wangdong","โรงเรียนบ้านวังด้ง","วังด้ง","บ้านวังด้ง"]},{"school_id":"phuphrom","name":"โรงเรียนบ้านพุพรหม","short_name":"พุพรหม","aliases":["phuphrom","โรงเรียนบ้านพุพรหม","พุพรหม","บ้านพุพรหม"]},{"school_id":"wangkhaokaew","name":"โรงเรียนบ้านวังเขาแก้ว","short_name":"วังเขาแก้ว","aliases":["wangkhaokaew","โรงเรียนบ้านวังเขาแก้ว","วังเขาแก้ว","บ้านวังเขาแก้ว"]},{"school_id":"saohong","name":"โรงเรียนบ้านเสาหงส์","short_name":"เสาหงส์","aliases":["saohong","โรงเรียนบ้านเสาหงส์","เสาหงส์","บ้านเสาหงส์"]},{"school_id":"nongkrathum","name":"โรงเรียนบ้านหนองกระทุ่ม","short_name":"หนองกระทุ่ม","aliases":["nongkrathum","โรงเรียนบ้านหนองกระทุ่ม","หนองกระทุ่ม","บ้านหนองกระทุ่ม"]}]'::jsonb) as x(school_id text,name text,short_name text,aliases text[])
 on conflict do nothing;
insert into public.nongkum_schedule_sports(sport_id,name,aliases)
select x.sport_id,x.name,x.aliases from jsonb_to_recordset('[{"sport_id":"football","name":"ฟุตบอล","aliases":["football","ฟุตบอล"]},{"sport_id":"shootout","name":"ยิงจุดโทษ","aliases":["shootout","ยิงจุดโทษ","จุดโทษ"]},{"sport_id":"futsal","name":"ฟุตซอล","aliases":["futsal","ฟุตซอล"]},{"sport_id":"volleyball","name":"วอลเลย์บอล","aliases":["volleyball","วอลเลย์บอล"]},{"sport_id":"takraw","name":"เซปักตะกร้อ","aliases":["takraw","เซปักตะกร้อ","ตะกร้อ"]},{"sport_id":"petanque","name":"เปตอง","aliases":["petanque","เปตอง"]},{"sport_id":"tabletennis","name":"เทเบิลเทนนิส","aliases":["tabletennis","เทเบิลเทนนิส","ปิงปอง"]},{"sport_id":"tugofwar","name":"ชักเย่อ","aliases":["tugofwar","ชักเย่อ"]},{"sport_id":"athletics","name":"กรีฑา","aliases":["athletics","กรีฑา","ลู่","วิ่ง"]}]'::jsonb) as x(sport_id text,name text,aliases text[])
 on conflict do nothing;
